CREATE OR REPLACE FUNCTION audit_row_changes()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    v_old jsonb;
    v_new jsonb;
    v_changed jsonb := '{}'::jsonb;
    v_pk jsonb;
    v_user text;
    v_key text;
    v_old_value jsonb;
    v_new_value jsonb;
BEGIN
    v_user := COALESCE(NULLIF(current_setting('app.current_user', true), ''), current_user);

    IF TG_OP = 'INSERT' THEN
        v_new := to_jsonb(NEW);
        v_pk := jsonb_build_object(TG_ARGV[0], v_new -> TG_ARGV[0]);
        v_changed := v_new;
    ELSIF TG_OP = 'UPDATE' THEN
        v_old := to_jsonb(OLD);
        v_new := to_jsonb(NEW);
        v_pk := jsonb_build_object(TG_ARGV[0], v_new -> TG_ARGV[0]);

        FOR v_key, v_new_value IN SELECT key, value FROM jsonb_each(v_new)
        LOOP
            v_old_value := v_old -> v_key;
            IF v_old_value IS DISTINCT FROM v_new_value THEN
                v_changed := v_changed || jsonb_build_object(
                    v_key,
                    jsonb_build_object('old', v_old_value, 'new', v_new_value)
                );
            END IF;
        END LOOP;
    ELSIF TG_OP = 'DELETE' THEN
        v_old := to_jsonb(OLD);
        v_pk := jsonb_build_object(TG_ARGV[0], v_old -> TG_ARGV[0]);
        v_changed := v_old;
    END IF;

    EXECUTE format(
        'INSERT INTO %I (audit_transaction_id, audit_operation, source_table, source_primary_key, old_values, new_values, changed_values, modified_by, modified_at)
         VALUES ($1,$2,$3,$4,$5,$6,$7,$8,now())',
        TG_TABLE_NAME || '_audit'
    )
    USING txid_current(), TG_OP, TG_TABLE_NAME, v_pk, v_old, v_new, v_changed, v_user;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_audit_sales_customers
AFTER INSERT OR UPDATE OR DELETE ON "sales_customers"
FOR EACH ROW EXECUTE FUNCTION audit_row_changes('customer_id');

CREATE TRIGGER trg_audit_sales_suppliers
AFTER INSERT OR UPDATE OR DELETE ON "sales_suppliers"
FOR EACH ROW EXECUTE FUNCTION audit_row_changes('supplier_id');

CREATE TRIGGER trg_audit_sales_franchises
AFTER INSERT OR UPDATE OR DELETE ON "sales_franchises"
FOR EACH ROW EXECUTE FUNCTION audit_row_changes('franchise_id');

CREATE TRIGGER trg_audit_sales_transactions
AFTER INSERT OR UPDATE OR DELETE ON "sales_transactions"
FOR EACH ROW EXECUTE FUNCTION audit_row_changes('transaction_id');

CREATE TRIGGER trg_audit_media_customer_reviews
AFTER INSERT OR UPDATE OR DELETE ON "media_customer_reviews"
FOR EACH ROW EXECUTE FUNCTION audit_row_changes('new_id');

CREATE TRIGGER trg_audit_media_gold_reviews_chunked
AFTER INSERT OR UPDATE OR DELETE ON "media_gold_reviews_chunked"
FOR EACH ROW EXECUTE FUNCTION audit_row_changes('chunk_id');

CREATE TABLE users_audit (
    audit_id BIGSERIAL PRIMARY KEY,
    audit_transaction_id UUID DEFAULT gen_random_uuid(),

    operation_type TEXT NOT NULL,

    modified_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    modified_by TEXT DEFAULT current_setting('app.current_user', true),
    modified_source TEXT DEFAULT current_setting('app.change_source', true),

    old_row_data JSONB,
    new_row_data JSONB
);

CREATE OR REPLACE FUNCTION audit_users_changes()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN

    IF TG_OP = 'INSERT' THEN

            operation_type,
            new_row_data
        )
        VALUES (
            'INSERT',
            to_jsonb(NEW)
        );

        RETURN NEW;

    ELSIF TG_OP = 'UPDATE' THEN

            operation_type,
            old_row_data,
            new_row_data
        )
        VALUES (
            'UPDATE',
            to_jsonb(OLD),
            to_jsonb(NEW)
        );

        RETURN NEW;

    ELSIF TG_OP = 'DELETE' THEN

            operation_type,
            old_row_data
        )
        VALUES (
            'DELETE',
            to_jsonb(OLD)
        );

        RETURN OLD;

    END IF;

    RETURN NULL;

END;
$$;

CREATE TRIGGER trg_users_audit
AFTER INSERT OR UPDATE OR DELETE
ON users
FOR EACH ROW
EXECUTE FUNCTION audit_users_changes();

