INSERT INTO "media_customer_reviews" ("new_id", "review", "franchise_id", "review_date") VALUES
    ('91', 'Unfortunately, I was quite disappointed with my recent purchase of Outback Oatmeal cookies from Bakehouse in Le Marais, Paris. The cookies were dry and lacked the oatmeal flavor I was expecting. Additionally, the Austin Almond Biscotti was overly sweet and crumbled easily, making it difficult to enjoy with my coffee. I had high hopes for Orchard Oasis, but it failed to deliver on its promise of a fruity burst of flavor. I hope Bakehouse can improve the quality of its products in the future.', '3000015', '2024-05-31T15:13:36.962Z'),
    ('92', 'Title: A Delightful Cookie Experience in Fitzroy, Melbourne
