INSERT INTO "media_gold_reviews_chunked" ("franchise_id", "review_date", "chunked_text", "review_uri") VALUES
    ('3000000', '2024-06-03T20:38:11.002Z', '"Underwhelming experience at Bakehouse in Bondi Beach, Sydney. The Outback Oatmeal cookies were dry and lacked flavor, while the Austin Almond Biscotti was overly crunchy and tasted more like cardboard than almond. The Orchard Oasis cookies were a confusing mix of sweet and savory, and the Golden Gate Ginger snaps were too spicy. The Tokyo Tidbits were the only decent option, but even those were overpriced. And don''t even get me started on the Pearly Pies - the crust was soggy and the filling was bland. Disappointing visit, won''t be back."', 's3://us-west-2-extstaging-managed-catalog-test-bucket-1/19a85dee-54bc-43a2-87ab-023d0ec16013/tables/dfc444c3-9af1-4c78-84eb-9020bacadff2'),
    ('3000001', '2024-06-03T20:38:11.002Z', '**1/5 stars**
INSERT INTO "media_gold_reviews_chunked" ("franchise_id", "review_date", "chunked_text", "review_uri") VALUES
    ('3000000', '2024-06-03T20:40:21.553Z', '"Underwhelming experience at Bakehouse in Bondi Beach, Sydney. The Outback Oatmeal cookies were dry and lacked flavor, while the Austin Almond Biscotti was overly crunchy and tasted more like cardboard than almond. The Orchard Oasis cookies were a confusing mix of sweet and savory, and the Golden Gate Ginger was overpowering. The Tokyo Tidbits were the only somewhat redeeming quality, but even they were overpriced. And don''t even get me started on the Pearly Pies - stale and flavorless. Won''t be back."', 's3://us-west-2-extstaging-managed-catalog-test-bucket-1/19a85dee-54bc-43a2-87ab-023d0ec16013/tables/dfc444c3-9af1-4c78-84eb-9020bacadff2'),
    ('3000001', '2024-06-03T20:40:21.553Z', '**1/5 stars**
INSERT INTO "media_gold_reviews_chunked" ("franchise_id", "review_date", "chunked_text", "review_uri") VALUES
    ('3000000', '2024-06-03T20:41:23.418Z', '"Underwhelming experience at Bakehouse in Bondi Beach, Sydney. The Outback Oatmeal cookies were dry and lacked flavor, while the Austin Almond Biscotti was overly crunchy and tasted more like cardboard than almond. The Orchard Oasis cookies were a confusing mix of sweet and savory, and the Golden Gate Ginger snaps were too spicy. The Tokyo Tidbits were the only decent option, but even those were overpriced. And don''t even get me started on the Pearly Pies - the crust was soggy and the filling was bland. Disappointing for a bakery in such a trendy location. 2/5 stars"', 's3://us-west-2-extstaging-managed-catalog-test-bucket-1/19a85dee-54bc-43a2-87ab-023d0ec16013/tables/dfc444c3-9af1-4c78-84eb-9020bacadff2'),
