INSERT INTO "media_gold_reviews_chunked" ("franchise_id", "review_date", "chunked_text", "review_uri") VALUES
    ('3000002', '2024-06-03T20:46:46.175Z', '"I''m obsessed with Bakehouse in San Francisco''s Mission district! Their Outback Oatmeal cookies are chewy perfection, packed with sweet and spicy flavors. The Austin Almond Biscotti are crunchy and nutty, perfect for dipping in coffee. But the real showstopper is the Orchard Oasis cookie sandwich - the combination of tart and sweet is absolute heaven. And don''t even get me started on the Golden Gate Ginger snaps, Tokyo Tidbits, and Pearly Pies... every bite is a delight! Bakehouse is a must-visit for any cookie lover"', 's3://us-west-2-extstaging-managed-catalog-test-bucket-1/19a85dee-54bc-43a2-87ab-023d0ec16013/tables/dfc444c3-9af1-4c78-84eb-9020bacadff2'),
    ('3000003', '2024-06-03T20:46:46.175Z', '"I''m obsessed with Bakehouse in Fitzroy, Melbourne! Their Outback Oatmeal cookies are chewy perfection, packed with sweet and spicy flavors. The Austin Almond Biscotti are crunchy and nutty, perfect for dunking. But the real showstoppers are the Orchard Oasis cookies, bursting with dried fruit and a hint of citrus. And don''t even get me started on the Golden Gate Ginger - spicy and addictive! The Tokyo Tidbits are adorable and delicious, and the Pearly Pies are a game-changer for dessert lovers. Five stars isn''t enough - I''d give Bakehouse ten stars if I could!"', 's3://us-west-2-extstaging-managed-catalog-test-bucket-1/19a85dee-54bc-43a2-87ab-023d0ec16013/tables/dfc444c3-9af1-4c78-84eb-9020bacadff2'),
    ('3000004', '2024-06-03T20:46:46.175Z', '"I''m obsessed with Bakehouse in Kitano, Kobe! Their Outback Oatmeal cookies are chewy perfection, packed with sweet and spicy flavors. The Austin Almond Biscotti is a game-changer - crunchy on the outside, soft on the inside, and utterly addictive. The Orchard Oasis cookie sandwiches are a refreshing twist on a classic, and the Golden Gate Ginger snaps are spicy and divine. But the real showstopper is the Tokyo Tidbits assortment - a delightful mix of flavors and textures that will leave you wanting more. And don''t even get me started on the Pearly Pies... heavenly! Five stars isn''t enough for this gem of a bakery!"', 's3://us-west-2-extstaging-managed-catalog-test-bucket-1/19a85dee-54bc-43a2-87ab-023d0ec16013/tables/dfc444c3-9af1-4c78-84eb-9020bacadff2'),
    ('3000005', '2024-06-03T20:46:46.175Z', '"I''m obsessed with Bakehouse in Silver Lake, Los Angeles! Their Outback Oatmeal cookies are chewy perfection, packed with sweet and spicy flavors. The Austin Almond Biscotti is a game-changer - crunchy on the outside, soft on the inside, and utterly addictive. But the real showstopper is the Orchard Oasis cookie sandwich - the combination of tart and sweet is pure magic. And don''t even get me started on the Golden Gate Ginger snaps... wow! The Tokyo Tidbits are a fun surprise, and the Pearly Pies are a decadent treat. Bakehouse, you''ve stolen my heart (and my taste buds)!"', 's3://us-west-2-extstaging-managed-catalog-test-bucket-1/19a85dee-54bc-43a2-87ab-023d0ec16013/tables/dfc444c3-9af1-4c78-84eb-9020bacadff2'),
